// Envelope 统一 JSON 信封 {code, message, data}
type Envelope struct {
	// Code 业务错误码；0 表示成功
	Code int `json:"code"`

	// Data 响应负载；形状随端点而变，由 allOf 组合的兄弟 schema 收窄
	Data interface{} `json:"data,omitempty"`

	// Message 人类可读信息；成功时为 "success"
	Message string `json:"message"`
}

// ErrorEnvelope 错误响应信封
type ErrorEnvelope struct {
	// Code 业务错误码（4xxxx 按区间映射 HTTP 状态：401xx→401，403xx→403，404xx→404，409xx→409，412xx→412，50xxx→500；502xx→502）
	Code int `json:"code"`

	// Data 恒为 null
	Data    map[string]interface{} `json:"data"`
	Message string                 `json:"message"`
}

